import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import * as adminApi from '@/services/adminApi';

export type AdminEntityType =
  | 'case'
  | 'phase'
  | 'level'
  | 'question'
  | 'evidence'
  | 'request'
  | 'suspect'
  | 'victim';

export function useAdminMutations(entityType: AdminEntityType) {
  const queryClient = useQueryClient();
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const clearFeedback = () => setFeedback(null);

  // Map the entity type to the exact API service functions from adminApi
  const apiMap = {
    'case': { create: adminApi.createAdminCase, update: adminApi.updateAdminCase, del: adminApi.deleteAdminCase, name: 'Case' },
    'phase': { create: adminApi.createAdminPhase, update: adminApi.updateAdminPhase, del: adminApi.deleteAdminPhase, name: 'Phase' },
    'level': { create: adminApi.createAdminLevel, update: adminApi.updateAdminLevel, del: adminApi.deleteAdminLevel, name: 'Level' },
    'question': { create: adminApi.createAdminQuestion, update: adminApi.updateAdminQuestion, del: adminApi.deleteAdminQuestion, name: 'Node' },
    'evidence': { create: adminApi.createAdminEvidence, update: adminApi.updateAdminEvidence, del: adminApi.deleteAdminEvidence, name: 'Evidence' },
    'request': { create: adminApi.createAdminInvestigationRequest, update: adminApi.updateAdminInvestigationRequest, del: adminApi.deleteAdminInvestigationRequest, name: 'Request protocol' },
    'suspect': { create: adminApi.createAdminSuspect, update: adminApi.updateAdminSuspect, del: adminApi.deleteAdminSuspect, name: 'Suspect' },
    'victim': { create: adminApi.createAdminVictim, update: adminApi.updateAdminVictim, del: adminApi.deleteAdminVictim, name: 'Victim' },
  };

  const methods = apiMap[entityType];

  const handleSuccess = (action: string) => {
    setFeedback({ type: 'success', message: `${methods.name} successfully ${action}.` });
    // This instantly refreshes the data in useAdminData across the whole app
    queryClient.invalidateQueries({ queryKey: ['adminCases'] });
  };

  const handleError = (error: Error) => {
    setFeedback({ type: 'error', message: error.message });
  };

  const createMutation = useMutation({
    mutationFn: async (formData: FormData) => {
      const result = await methods.create(formData);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('created'),
    onError: handleError,
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, formData }: { id: number, formData: FormData }) => {
      const result = await methods.update(id, formData);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('updated'),
    onError: handleError,
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      const result = await methods.del(id);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => handleSuccess('deleted'),
    onError: handleError,
  });

  const isProcessing = createMutation.isPending || updateMutation.isPending || deleteMutation.isPending;

  return {
    createEntity: createMutation.mutate,
    updateEntity: updateMutation.mutate,
    deleteEntity: deleteMutation.mutate,
    isProcessing,
    feedback,
    setFeedback,
    clearFeedback
  };
}

import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { login, register, getToken } from '@/services/auth';
import type { User } from '@/types';

// Authoritative Session Verification Hook
export function useAuthSession() {
  return useQuery({
    queryKey: ['authUser'],
    queryFn: async () => {
      const token = getToken();
      if (!token) throw new Error('No authentication token found.');

      const backendUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';
      const response = await fetch(`${backendUrl}/api/user`, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!response.ok) {
        throw new Error('Session verification failed. Unauthorized access.');
      }

      return response.json();
    },
    retry: false,
    staleTime: 1000 * 60 * 5, // Cache the authoritative user object for 5 minutes
  });
}

export function useAuth(onSuccess: (user: User) => void) {
  const queryClient = useQueryClient();
  const [isLogin, setIsLogin] = useState(true);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [name, setName] = useState('');

  const authMutation = useMutation({
    mutationFn: async () => {
      const result = isLogin
        ? await login(email, password)
        : await register(username, name, email, password);

      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: (data) => {
      // Seed the cache with the trusted server response directly
      queryClient.setQueryData(['authUser'], data.user);
      onSuccess(data.user);
    }
  });

  const toggleAuthMode = () => {
    setIsLogin(!isLogin);
    authMutation.reset();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    authMutation.mutate();
  };

  return {
    isLogin, toggleAuthMode,
    isLoading: authMutation.isPending,
    error: authMutation.error?.message || null,
    email, setEmail,
    password, setPassword,
    username, setUsername,
    name, setName,
    handleSubmit
  };
}

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { joinRoom, fetchRoomState } from '@/services/api';
import type { GameRoom, Evidence, Suspect, Victim } from '@/types';

export function useGameRoom(inviteCode: string | undefined) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const {
    data: room,
    isLoading,
    error,
    refetch
  } = useQuery({
    queryKey: ['gameRoom', inviteCode],
    queryFn: async () => {
      if (!inviteCode) throw new Error(t('pages.gameRoom.noInviteCode'));

      const storageKey = `active_room_id_for_${inviteCode}`;
      let roomId = sessionStorage.getItem(storageKey);

      if (!roomId) {
        const joinResult = await joinRoom(inviteCode);
        if (!joinResult.isSuccess) throw new Error(joinResult.errorMessage);

        roomId = joinResult.value.id.toString();
      }

      const stateResult = await fetchRoomState(parseInt(roomId, 10));
      if (!stateResult.isSuccess) throw new Error(stateResult.errorMessage);

      return stateResult.value;
    },
    enabled: !!inviteCode,
  });

  // Handle the side-effect purely based on successful data resolution
  useEffect(() => {
    if (room?.id && inviteCode) {
      sessionStorage.setItem(`active_room_id_for_${inviteCode}`, room.id.toString());
    }
  }, [room?.id, inviteCode]);

  // Expose a pure cache patching function to enforce the "Zero-Refetch" rule
  const patchRoomData = (updater: (oldRoom: GameRoom) => GameRoom) => {
    if (inviteCode) {
      queryClient.setQueryData(['gameRoom', inviteCode], (oldData: GameRoom | undefined) => {
        if (!oldData) return oldData;
        return updater(oldData);
      });
    }
  };

  const caseEvidences = room?.game_case?.evidences || [];
  const unlockedEvidenceIds = new Set(room?.unlocked_evidences?.map((e: Evidence) => e.id) || []);
  const accumulatedEvidences: Evidence[] = caseEvidences.filter(
    (evidence: Evidence) => evidence.is_initial || unlockedEvidenceIds.has(evidence.id)
  );

  const caseSuspects = room?.game_case?.suspects || [];
  const unlockedSuspectIds = new Set(room?.unlocked_suspects?.map((s: Suspect) => s.id) || []);
  const accumulatedSuspects: Suspect[] = caseSuspects.filter(
    (suspect: Suspect) => suspect.is_initial || unlockedSuspectIds.has(suspect.id)
  );

  const caseVictims = room?.game_case?.victims || [];
  const unlockedVictimIds = new Set(room?.unlocked_victims?.map((v: Victim) => v.id) || []);
  const accumulatedVictims: Victim[] = caseVictims.filter(
    (victim: Victim) => victim.is_initial || unlockedVictimIds.has(victim.id)
  );

  return {
    room,
    isLoading,
    error: error instanceof Error ? error.message : null,
    accumulatedEvidences,
    accumulatedSuspects,
    accumulatedVictims,
    refreshRoomData: async () => { await refetch(); },
    patchRoomData
  };
}

import { useState, useEffect } from 'react';
import { useMutation } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { useRoomState, useRoomActions } from '@/context/RoomContext';
import type { Choice } from '@/types';
import { lockVote, submitAssessment, initiatePhase, triggerWiretap } from '@/services/api';

export type { ToastNotification, GlobalFeedback } from '@/context/RoomContext';

interface ApiError { title?: string; message: string; }

export function useInvestigationPhase() {
  const { t } = useTranslation();
  const { room } = useRoomState();
  const { refreshRoomData, addGlobalToast, setGlobalFeedback } = useRoomActions();

  const [localVotes, setLocalVotes] = useState<Record>({});
  const roomId = room.id;

  useEffect(() => {
    const storedUser = localStorage.getItem('auth_user');
    const currentUser = storedUser ? JSON.parse(storedUser) : null;
    if (!currentUser) return;

    const serverVotes: Record = {};
    room.votes?.forEach((vote: any) => {
      if (vote.user_id === currentUser.id) {
        serverVotes[vote.question_id] = vote.choice_id;
      }
    });
    setLocalVotes(serverVotes);
  }, [room.votes]);

  const voteMutation = useMutation({
    mutationFn: async ({ questionId, choiceId }: { questionId: number, choiceId: number }) => {
      const result = await lockVote(roomId, questionId, choiceId);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onSuccess: () => {
      refreshRoomData();
    }
  });

  const submitTheoryMutation = useMutation({
    mutationFn: async () => {
      const result = await submitAssessment(roomId);
      if (!result.isSuccess) throw { message: result.errorMessage };
      return result.value;
    },
    onSuccess: async (data) => {
      if (data.status === 'success' || data.status === 'failed_final') {
        setGlobalFeedback({
          type: data.status === 'success' ? 'success' : 'error',
          title: data.status === 'success' ? t('pages.gameRoom.hooks.phase.consensusVerified') : t('pages.gameRoom.hooks.phase.theoryRejected'),
          message: data.message
        });

        setTimeout(() => {
          setGlobalFeedback(null);
          setLocalVotes({});
          refreshRoomData();
        }, 4000);
      } else {
        setGlobalFeedback({ type: 'error', title: t('pages.gameRoom.hooks.phase.theoryRejected'), message: data.message });
        setLocalVotes({});
        refreshRoomData();
      }
    },
    onError: (error: ApiError) => {
      setGlobalFeedback({ type: 'error', title: error.title || t('pages.gameRoom.hooks.phase.systemError'), message: error.message });
    }
  });

  const initiatePhaseMutation = useMutation({
    mutationFn: async (levelId: number) => {
      const result = await initiatePhase(roomId, levelId);
      if (!result.isSuccess) throw { message: result.errorMessage };
      return result.value;
    },
    onSuccess: () => refreshRoomData(),
    onError: (error: ApiError) => setGlobalFeedback({
      type: 'error', title: error.title || t('pages.gameRoom.hooks.phase.systemError'), message: error.message
    })
  });

  const triggerWiretapMutation = useMutation({
    mutationFn: async ({ questionId, audioUrl }: { questionId: number, audioUrl: string }) => {
      const result = await triggerWiretap(roomId, questionId);
      if (!result.isSuccess) throw { message: result.errorMessage };
      return { value: result.value, audioUrl };
    },
    onSuccess: () => {
      refreshRoomData();
    },
    onError: (error: ApiError) => setGlobalFeedback({
      type: 'error', title: error.title || t('pages.gameRoom.hooks.phase.transmissionError'), message: error.message
    })
  });

  const handleSelectChoice = (e: React.MouseEvent, questionId: number, choice: Choice, status: string) => {
    e.stopPropagation();
    if (status !== 'active') return;

    setLocalVotes(prev => ({ ...prev, [questionId]: choice.id }));

    if (choice.outcomes?.unlock_evidence && choice.outcomes.unlock_evidence.length > 0) {
      addGlobalToast({
        type: 'evidence',
        title: t('pages.gameRoom.hooks.phase.evidenceRecovered'),
        message: t('pages.gameRoom.hooks.phase.evidenceRecoveredMsg', { count: choice.outcomes.unlock_evidence.length }),
        icon: 'https://api.iconify.design/ph:file-magnifying-glass-duotone.svg?color=%23c48b36'
      });
    }
    if (choice.outcomes?.unlock_levels && choice.outcomes.unlock_levels.length > 0) {
      addGlobalToast({
        type: 'level',
        title: t('pages.gameRoom.hooks.phase.phaseUnlocked'),
        message: t('pages.gameRoom.hooks.phase.phaseUnlockedMsg'),
        icon: 'https://api.iconify.design/ph:git-merge-duotone.svg?color=%235a8a9e'
      });
    }
    if (choice.outcomes?.unlock_suspects && choice.outcomes.unlock_suspects.length > 0) {
      addGlobalToast({
        type: 'suspect',
        title: t('pages.gameRoom.hooks.phase.personOfInterest'),
        message: t('pages.gameRoom.hooks.phase.personOfInterestMsg'),
        icon: 'https://api.iconify.design/ph:user-focus-duotone.svg?color=%23a33232'
      });
    }
    if (choice.outcomes?.unlock_victims && choice.outcomes.unlock_victims.length > 0) {
      addGlobalToast({
        type: 'victim',
        title: t('pages.gameRoom.hooks.phase.casualtyIdentified'),
        message: t('pages.gameRoom.hooks.phase.casualtyIdentifiedMsg'),
        icon: 'https://api.iconify.design/ph:skull-duotone.svg?color=%238a8d91'
      });
    }

    voteMutation.mutate({ questionId, choiceId: choice.id });
  };

  const handleSubmitTheory = (e: React.MouseEvent) => {
    e.stopPropagation();
    submitTheoryMutation.mutate();
  };

  const clearFeedback = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setGlobalFeedback(null);
  };

  return {
    localVotes,
    isSubmitting: submitTheoryMutation.isPending || voteMutation.isPending,
    isInitiating: initiatePhaseMutation.isPending,
    handleSelectChoice,
    handleSubmitTheory,
    initiatePhase: (levelId: number) => initiatePhaseMutation.mutate(levelId),
    clearFeedback,
    triggerWiretap: (questionId: number, audioUrl: string) => triggerWiretapMutation.mutate({ questionId, audioUrl }),
    isTriggeringWiretap: triggerWiretapMutation.isPending,
    addToast: addGlobalToast
  };
}

import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { submitInvestigationRequest } from '@/services/api';
import type { GameRoom } from '@/types';
import type { ToastNotification } from './useInvestigationPhase';

export interface FiledRequest {
  id: number | string;
  request_type: string;
  created_at: string;
  evidence_ids: number[];
}

export function useInvestigationRequest(room: GameRoom, refreshRoomData: () => void) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();

  const [trayEvidences, setTrayEvidences] = useState([]);
  const [requestType, setRequestType] = useState('');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [toasts, setToasts] = useState([]);

  // Derived directly from the authoritative room payload
  const filedRequests: FiledRequest[] = room.filed_requests || [];

  const requestMutation = useMutation({
    mutationFn: async () => {
      const result = await submitInvestigationRequest(room.id, trayEvidences);
      if (!result.isSuccess) throw new Error(result.errorMessage);
      return result.value;
    },
    onMutate: async () => {
      await queryClient.cancelQueries({ queryKey: ['gameRoom', room.invite_code] });
      const previousRoom = queryClient.getQueryData(['gameRoom', room.invite_code]);

      const optimisticRequest: FiledRequest = {
        id: `temp-${Date.now()}`,
        request_type: requestType,
        created_at: new Date().toISOString(),
        evidence_ids: [...trayEvidences]
      };

      queryClient.setQueryData(['gameRoom', room.invite_code], (old: any) => {
        if (!old) return old;
        return {
          ...old,
          filed_requests: [optimisticRequest, ...(old.filed_requests || [])]
        };
      });

      return { previousRoom };
    },
    onError: (error: Error, _variables: void, context: any) => {
      queryClient.setQueryData(['gameRoom', room.invite_code], context?.previousRoom);
      setFeedback({ type: 'error', message: error.message });
      setTrayEvidences([]);
    },
    onSuccess: (data) => {
      setFeedback({ type: 'success', message: data.message });
      setTrayEvidences([]);
      setRequestType('');
      refreshRoomData();

      // Trigger respective toast notifications based on what the DA unlocked
      setTimeout(() => {
        const newToasts: ToastNotification[] = [];

        if (data.unlocked_evidence && data.unlocked_evidence.length > 0) {
          newToasts.push({
            id: crypto.randomUUID(),
            type: 'evidence',
            title: t('pages.gameRoom.hooks.request.proceduralApproved'),
            message: t('pages.gameRoom.hooks.request.proceduralApprovedMsg'),
            icon: 'https://api.iconify.design/ph:file-magnifying-glass-duotone.svg?color=%23c48b36'
          });
        }

        if (data.unlocked_levels && data.unlocked_levels.length > 0) {
          newToasts.push({
            id: crypto.randomUUID(),
            type: 'level',
            title: t('pages.gameRoom.hooks.request.warrantExecuted'),
            message: t('pages.gameRoom.hooks.request.warrantExecutedMsg'),
            icon: 'https://api.iconify.design/ph:git-merge-duotone.svg?color=%235a8a9e'
          });
        }

        if (newToasts.length > 0) {
          setToasts(prev => [...prev, ...newToasts]);
          setTimeout(() => {
            setToasts((prev) => prev.filter((t) => !newToasts.some((nt) => nt.id === t.id)));
          }, 5000);
        }
      }, 500);
    }
  });

  const addToTray = (evidenceId: number) => {
    if (!trayEvidences.includes(evidenceId)) {
      setTrayEvidences([...trayEvidences, evidenceId]);
    }
  };

  const removeFromTray = (evidenceId: number) => {
    setTrayEvidences(trayEvidences.filter(id => id !== evidenceId));
  };

  const clearFeedback = () => setFeedback(null);

  return {
    trayEvidences,
    requestType,
    setRequestType,
    addToTray,
    removeFromTray,
    isSubmitting: requestMutation.isPending,
    feedback,
    toasts,
    clearFeedback,
    submitRequest: requestMutation.mutate,
    filedRequests
  };
}

import { useState, useCallback, useEffect } from 'react';

// Define the allowed entities so TypeScript strictly guards your scaling
type TrackableEntity = 'evidence' | 'suspects' | 'locations' | 'victims';

export function useViewedItems(roomKey: string | number | undefined, entityType: TrackableEntity) {
  // Use the roomKey in the namespace
  const storageKey = roomKey ? `room_${roomKey}_viewed_${entityType}` : null;

  const [viewedItems, setViewedItems] = useState<Set>(() => {
    if (!storageKey) return new Set();
    try {
      const stored = sessionStorage.getItem(storageKey);
      return stored ? new Set(JSON.parse(stored)) : new Set();
    } catch { return new Set(); }
  });

  useEffect(() => {
    if (!storageKey) return;
    const stored = sessionStorage.getItem(storageKey);
    if (stored) {
      setViewedItems(new Set(JSON.parse(stored)));
    }
  }, [storageKey]);

  const markItemAsViewed = useCallback((id: number) => {
    if (!storageKey) return;

    setViewedItems(prev => {
      if (prev.has(id)) return prev;

      const nextViewed = new Set(prev);
      nextViewed.add(id);

      sessionStorage.setItem(storageKey, JSON.stringify(Array.from(nextViewed)));

      return nextViewed;
    });
  }, [storageKey]);

  return { viewedItems, markItemAsViewed };
}

