import { useState, useRef } from 'react';
import { useAdminData } from '@/hooks/useAdminData';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import EntityList from './Shared/EntityList';
import type { GameCase } from '@/types';

export default function CaseForm() {
  const [editingCaseId, setEditingCaseId] = useState(null);

  const [title, setTitle] = useState('');
  const [story, setStory] = useState('');
  const [minPlayerXP, setMinPlayerXP] = useState('0');
  const [xpOnSolve, setXpOnSolve] = useState('100');
  const [maxStrikes, setMaxStrikes] = useState('5');
  const [image, setImage] = useState(null);
  const [ratingStars, setRatingStars] = useState('5.0');
  const [ageRating, setAgeRating] = useState('Mature 17+');
  const [estimatedPlaytime, setEstimatedPlaytime] = useState('60 Minutes');
  const [difficulty, setDifficulty] = useState('Standard');
  const [tags, setTags] = useState('');
  const [authorName, setAuthorName] = useState('System');
  const [isPublished, setIsPublished] = useState(false);
  const [storeLocally, setStoreLocally] = useState(false);
  const fileInputRef = useRef(null);

  const { data: cases = [], isLoading: isFetchingCases } = useAdminData();

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback, clearFeedback
  } = useAdminMutations('case');

  const clearForm = () => {
    setEditingCaseId(null);
    setTitle(''); setStory(''); setMinPlayerXP('0'); setXpOnSolve('100');
    setMaxStrikes('5'); setRatingStars('5.0'); setAgeRating('Mature 17+');
    setEstimatedPlaytime('60 Minutes'); setDifficulty('Standard'); setTags('');
    setAuthorName('System'); setIsPublished(false); setStoreLocally(false);
    setImage(null); clearFeedback();
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    clearFeedback();

    const formData = new FormData();
    formData.append('title', title); formData.append('story', story);
    formData.append('min_player_XP', minPlayerXP); formData.append('XP_on_solve', xpOnSolve);
    formData.append('max_strikes', maxStrikes); formData.append('rating_stars', ratingStars);
    formData.append('age_rating', ageRating); formData.append('estimated_playtime', estimatedPlaytime);
    formData.append('difficulty', difficulty); formData.append('tags', tags);
    formData.append('author_name', authorName); formData.append('is_published', isPublished ? '1' : '0');
    formData.append('store_locally', storeLocally ? '1' : '0');
    if (image) formData.append('image', image);

    if (editingCaseId) {
      updateEntity({ id: editingCaseId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
    }
  };

  const handleEditInit = (caseObj: GameCase) => {
    clearFeedback();
    setEditingCaseId(caseObj.id);
    setTitle(caseObj.title); setStory(caseObj.story);
    setMinPlayerXP(caseObj.min_player_XP?.toString() || '0');
    setXpOnSolve(caseObj.XP_on_solve?.toString() || '100');
    setMaxStrikes(caseObj.max_strikes?.toString() || '5');
    setRatingStars(caseObj.rating_stars?.toString() || '5.0');
    setAgeRating(caseObj.age_rating || 'Mature 17+');
    setEstimatedPlaytime(caseObj.estimated_playtime || '60 Minutes');
    setDifficulty(caseObj.difficulty || 'Standard');
    setTags(Array.isArray(caseObj.tags) ? caseObj.tags.join(', ') : (caseObj.tags || ''));
    setAuthorName(caseObj.author_name || 'System');
    setIsPublished(!!caseObj.is_published);

    setImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (c: GameCase) => {
    if (window.confirm(`Are you absolutely sure you want to delete "${c.title}"? All nested levels, evidence, and media will be wiped permanently.`)) {
      if (editingCaseId === c.id) clearForm();
      deleteEntity(c.id);
    }
  };

  return (









            {editingCaseId ? `// Editing Case ID: ${editingCaseId}` : '// Initialize New Case'}

          {editingCaseId && (
            Cancel Edit
          )}


        {feedback && 
{feedback.message}}




             setIsPublished(e.target.checked)} style={{ transform: 'scale(1.5)', accentColor: isPublished ? 'var(--accent-cyan)' : 'var(--accent-crimson)' }} />

              {isPublished ? 'LIVE / PUBLISHED' : 'DRAFT / CLASSIFIED'} : {isPublished ? 'This case is visible to all agents on the main board.' : 'This case is hidden from the public. Only visible in Admin Oversight.'}




Case Title setTitle(e.target.value)} />

Official Briefing (Story) setStory(e.target.value)} />




Minimum XP Required setMinPlayerXP(e.target.value)} />

XP Reward on Solve setXpOnSolve(e.target.value)} />

Allowed Strikes (Difficulty) setMaxStrikes(e.target.value)} />





Difficulty setDifficulty(e.target.value)} />

Est. Playtime setEstimatedPlaytime(e.target.value)} />

Content Rating setAgeRating(e.target.value)} />





User Rating (0.0 to 5.0) setRatingStars(e.target.value)} />

Author / Creator setAuthorName(e.target.value)} />



Genre Tags (Comma Separated) setTags(e.target.value)} />



            Cover Image {editingCaseId && '(Leave blank to keep existing image)'}

Optimal: 1:1 (Square) or 16:9 ratio. Min 800x800px. WEBP or JPG format. Max 4MB.
             setImage(e.target.files?.[0] || null)} />




             setStoreLocally(e.target.checked)} style={{ transform: 'scale(1.3)', accentColor: 'var(--accent-amber)' }} />
            Store Locally on Server: Save assets directly to public server folders instead of Cloudinary.



            {isProcessing ? 'Processing Data...' : editingCaseId ? 'Update Existing Case' : 'Commit Case to Database'}




      <EntityList
        title="Manage Existing Cases"
        items={cases}
        emptyMessage={isFetchingCases ? "Loading archive..." : "No cases in database."}
        keyExtractor={(c) => c.id}
        isProcessing={isProcessing}
        onEdit={handleEditInit}
        onDelete={handleDelete}
        renderItemContent={(c) => (
          <>

              [{c.is_published ? 'PUBLISHED' : 'DRAFT'}]

            ID: {c.id}
            {c.title}
          </>
        )}
      />

  );
}

import { useState, useRef } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import EntityList from './Shared/EntityList';
import EvidenceMetadataFields from './Shared/EvidenceMetadataFields';
import type { Evidence } from '@/types/evidence';

export default function EvidenceForm() {
  const [editingId, setEditingId] = useState(null);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [evidenceType, setEvidenceType] = useState('document');
  const [subType, setSubType] = useState('');
  const [metadata, setMetadata] = useState<Record>({});

  const [isInitial, setIsInitial] = useState(true);
  const [isVitalForConviction, setIsVitalForConviction] = useState(false);
  const [storeLocally, setStoreLocally] = useState(false);

  const [image, setImage] = useState(null);
  const [audio, setAudio] = useState(null);

  const imageInputRef = useRef(null);
  const audioInputRef = useRef(null);

  const { caseId, selectedCase } = useAdminContext();

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback, clearFeedback
  } = useAdminMutations('evidence');

  if (!caseId || !selectedCase) {
    return (



[ MISSING CONTEXT: NO CASE SELECTED ]

Please select a Target Case from the Global Directory to manage Evidence.

    );
  }

  const clearForm = () => {
    setEditingId(null);
    setTitle(''); setDescription('');
    setSubType(''); setMetadata({});
    setIsInitial(true); setIsVitalForConviction(false); setStoreLocally(false);
    setImage(null); setAudio(null);
    clearFeedback();
    if (imageInputRef.current) imageInputRef.current.value = '';
    if (audioInputRef.current) audioInputRef.current.value = '';
  };

  // When changing the top-level type, wipe the previous sub_type and metadata payload to prevent corruption
  const handleTypeChange = (e: React.ChangeEvent) => {
    setEvidenceType(e.target.value);
    setSubType('');
    setMetadata({});
  };

  const updateMeta = (key: string, value: any) => {
    setMetadata(prev => ({ ...prev, [key]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    clearFeedback();

    const formData = new FormData();
    formData.append('case_id', caseId);
    formData.append('title', title);
    formData.append('evidence_type', evidenceType);
    formData.append('description', description);
    formData.append('is_initial', isInitial ? '1' : '0');
    formData.append('is_vital_for_conviction', isVitalForConviction ? '1' : '0');
    formData.append('store_locally', storeLocally ? '1' : '0');

    // Append the new structured fields
    if (subType) formData.append('sub_type', subType);
    if (Object.keys(metadata).length > 0) {
      formData.append('metadata', JSON.stringify(metadata));
    }

  if ((evidenceType === 'image' || subType === 'background_check') && image) {
    formData.append('image', image);
  }
    if (evidenceType === 'audio' && audio) formData.append('audio', audio);

    if (editingId) {
      updateEntity({ id: editingId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
    }
  };

  const handleEdit = (ev: Evidence | any) => {
    setEditingId(ev.id);
    setTitle(ev.title);
    setDescription(ev.description || '');
    setEvidenceType(ev.evidence_type);
    setSubType(ev.sub_type || '');
    setMetadata(ev.metadata || {});

    setIsInitial(!!ev.is_initial);
    setIsVitalForConviction(!!ev.is_vital_for_conviction);
    setImage(null); setAudio(null);
    clearFeedback();

    if (imageInputRef.current) imageInputRef.current.value = '';
    if (audioInputRef.current) audioInputRef.current.value = '';
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (ev: Evidence) => {
    if (window.confirm(`Are you absolutely sure you want to delete "${ev.title}"?`)) {
      if (editingId === ev.id) clearForm();
      deleteEntity(ev.id);
    }
  };

  return (










              {editingId ? `// Editing Evidence ID: ${editingId}` : '// Initialize New Evidence'}

            Targeting Case: {selectedCase.title}

          {editingId && Cancel Edit}


        {feedback && 
{feedback.message}}




             setIsInitial(e.target.checked)} style={{ transform: 'scale(1.5)', accentColor: 'var(--accent-cyan)' }} />
            Initial Evidence: Available on the board immediately.




             setIsVitalForConviction(e.target.checked)} style={{ transform: 'scale(1.5)', accentColor: 'var(--accent-crimson)' }} />
            Vital Evidence: Required to secure a conviction.




            Master Evidence Category

              Written Document
              Witness Testimony
              Forensic Report
              Audio Recording
              Photographic Evidence




Evidence Title setTitle(e.target.value)} />

Short Description (Hover text / Caption) setDescription(e.target.value)} />

          {/* DYNAMIC METADATA COMPONENT INJECTION */}


          {(evidenceType === 'image' || subType === 'background_check') && (


              {subType === 'background_check' ? 'Subject Mugshot / ID Photo' : 'Evidence Image'}


                Optimal: 1:1 or 3:4 portrait. WEBP or JPG. Max 4MB.

               setImage(e.target.files?.[0] || null)} />

          )}

          {evidenceType === 'audio' && (


              Audio Recording

Optimal: MP3 or WAV format. Compressed for web streaming. Max 10MB.
               setAudio(e.target.files?.[0] || null)} />

          )}

          {(evidenceType === 'image' || evidenceType === 'audio' || subType === 'background_check') && (


               setStoreLocally(e.target.checked)} style={{ transform: 'scale(1.3)', accentColor: 'var(--accent-amber)' }} />

                Store Locally on Server: Save assets directly to public server folders instead of Cloudinary.


          )}


            {isProcessing ? 'Processing Data...' : editingId ? 'Update Evidence' : 'Commit Evidence'}




      <EntityList
        title="Case Evidence"
        items={selectedCase.evidences || []}
        emptyMessage="No evidence secured for this case."
        keyExtractor={(ev) => ev.id.toString()}
        isProcessing={isProcessing}
        onEdit={handleEdit}
        onDelete={handleDelete}
        renderItemContent={(ev: any) => (
          <>

              EX-{ev.id.toString().padStart(3, '0')}

            {ev.title}
            {ev.sub_type && (

                {ev.sub_type.replace('_', ' ')}

            )}
          </>
        )}
      />

  );
}

import { useState } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import { getInvestigationRequestLabel } from '@/types';
import EntityList from './Shared/EntityList';
import type { Evidence, Level, InvestigationRequest, InvestigationRequestType } from '@/types';

export default function InvestigationRequestForm() {
  const [editingId, setEditingId] = useState(null);
  const [requestType, setRequestType] = useState('search_warrant');
  const [requiredEvidenceIds, setRequiredEvidenceIds] = useState([]);
  const [unlocksEvidenceId, setUnlocksEvidenceId] = useState('');
  const [unlocksLevelId, setUnlocksLevelId] = useState('');

  const { caseId, selectedCase } = useAdminContext();

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback, setFeedback, clearFeedback
  } = useAdminMutations('request');

  if (!caseId || !selectedCase) {
    return (



[ MISSING CONTEXT: NO CASE SELECTED ]

Please select a Target Case from the Global Directory to map Procedural Combos.

    );
  }

  const clearForm = () => {
    setEditingId(null);
    setRequestType('search_warrant');
    setRequiredEvidenceIds([]); setUnlocksEvidenceId(''); setUnlocksLevelId('');
    clearFeedback();
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    clearFeedback();

    if (requiredEvidenceIds.length < 2) return setFeedback({ type: 'error', message: 'At least two pieces of evidence are required to build a combo.' });
    if (!unlocksEvidenceId && !unlocksLevelId) return setFeedback({ type: 'error', message: 'The request must yield at least one reward (Evidence or Level).' });

    const formData = new FormData();
    formData.append('case_id', caseId);
    formData.append('request_type', requestType);
    if (unlocksEvidenceId) formData.append('unlocks_evidence_id', unlocksEvidenceId);
    if (unlocksLevelId) formData.append('unlocks_level_id', unlocksLevelId);

    requiredEvidenceIds.forEach(id => {
      formData.append('required_evidence_ids[]', id);
    });

    if (editingId) {
      updateEntity({ id: editingId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
    }
  };

  const handleEdit = (req: InvestigationRequest) => {
    setEditingId(req.id);
    setRequestType(req.request_type);
    setRequiredEvidenceIds(req.required_evidences?.map((ev: Evidence) => ev.id.toString()) || []);
    setUnlocksEvidenceId(req.unlocks_evidence_id?.toString() || '');
    setUnlocksLevelId(req.unlocks_level_id?.toString() || '');
    clearFeedback();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (req: InvestigationRequest) => {
    if (window.confirm(`Are you sure you want to delete this ${getInvestigationRequestLabel(req.request_type)} protocol?`)) {
      if (editingId === req.id) clearForm();
      deleteEntity(req.id);
    }
  };

  const allCaseLevels: Level[] = selectedCase.phases?.flatMap(p => p.levels || []) || [];

  return (










              {editingId ? `// Editing Request ID: ${editingId}` : '// Compile New Request Protocol'}

            Targeting Case: {selectedCase.title}

          {editingId && Cancel Edit}


        {feedback && 
{feedback.message}}




            Request Category
             setRequestType(e.target.value)}>
              {getInvestigationRequestLabel('search_warrant')}
              {getInvestigationRequestLabel('financial_subpoena')}
              {getInvestigationRequestLabel('toxicology_report')}
              {getInvestigationRequestLabel('wiretap_authorization')}
              {getInvestigationRequestLabel('ballistics_analysis')}
              {getInvestigationRequestLabel('digital_forensics')}
              {getInvestigationRequestLabel('exhumation_order')}





            [ THE PUZZLE ] Required Evidence Combination


              Players must submit ALL selected evidence items in the tray to get approval. (Hold Ctrl/Cmd to multi-select).

             setRequiredEvidenceIds(Array.from(e.target.selectedOptions, opt => opt.value))}
            >
              {selectedCase.evidences?.map((ev: Evidence) => (
                EX-{ev.id.toString().padStart(3, '0')} : {ev.title}
              ))}







              [ THE REWARD ] Unlocks Evidence
               setUnlocksEvidenceId(e.target.value)}>
                -- No Evidence Reward --
                {selectedCase.evidences?.filter(ev => !ev.is_initial).map((ev: Evidence) => (
                  EX-{ev.id.toString().padStart(3, '0')} : {ev.title}
                ))}




              [ THE REWARD ] Unlocks Phase/Level
               setUnlocksLevelId(e.target.value)}>
                -- No Level Reward --
                {allCaseLevels.filter(l => !l.is_initial).map((l: Level) => (
                  Level {l.order_index} : {l.title}
                ))}





            {isProcessing ? 'Processing Data...' : editingId ? 'Update Protocol' : 'Commit Protocol to Database'}




      <EntityList
        title="Active Request Protocols"
        items={selectedCase.investigation_requests || []}
        emptyMessage="No request protocols built for this case."
        keyExtractor={(req) => req.id}
        isProcessing={isProcessing}
        onEdit={handleEdit}
        onDelete={handleDelete}
        renderItemContent={(req) => (
          <>
            REQ-{req.id}
            {getInvestigationRequestLabel(req.request_type)}


              Requires {req.required_evidences?.length || 0} items
              {(req.unlocks_evidence_id || req.unlocks_level_id) && ' • 🎁 Has Reward'}

          </>
        )}
      />

  );
}

import { useState } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import EntityList from './Shared/EntityList';
import type { Phase } from '@/types';

export default function PhaseForm() {
  const [editingId, setEditingId] = useState(null);
  const [title, setTitle] = useState('');
