import type { Question, Evidence, Level, Suspect, Victim } from '@/types';
import { type DraftChoice } from '../Shared/ChoiceEditorCard';

interface AdminInterrogationFormProps {
  isSaved: boolean;
  nodeId: number | string;
  text: string;
  setText: (text: string) => void;
  choices: DraftChoice[];
  updateChoice: (id: string, field: string, value: any, category?: 'outcomes' | 'requirements') => void;
  addChoice: () => void;
  removeChoice: (id: string) => void;
  showAdvanced: Record;
  setShowAdvanced: (val: Record) => void;
  handleSave: () => void;
  handleDelete: () => void;
  isProcessing: boolean;
  feedback: { type: 'success' | 'error'; message: string } | null;

  // The global asset directories
  allSavedNodes: Question[];
  availableEvidences: Evidence[];
  availableLevels: Level[];
  availableSuspects: Suspect[];
  availableVictims: Victim[];
}

export default function AdminInterrogationForm({
  isSaved, nodeId, text, setText, choices, updateChoice, addChoice, removeChoice,
  showAdvanced, setShowAdvanced, handleSave, handleDelete, isProcessing, feedback,
  allSavedNodes, availableEvidences, availableLevels, availableSuspects, availableVictims
}: AdminInterrogationFormProps) {

  // Map out all choices from all OTHER saved nodes to use as prerequisites
  const allAvailablePriorChoices = allSavedNodes
    .filter(n => n.id !== nodeId)
    .flatMap(node =>
      (node.choices || []).map(c => ({
        id: c.id,
        label: `Node ${node.id}: "${c.text.substring(0, 30)}..."`
      }))
    );

  return (




        {isSaved ? `NODE ID: ${nodeId}` : 'UNSAVED DRAFT NODE'}
        {feedback && {feedback.message}}






          Suspect Dialogue
           setText(e.target.value)} style={{ minHeight: '80px' }} placeholder="Suspect says..." />




          Player Responses & Branches
          {choices.map((choice) => (


               updateChoice(choice.id as string, 'text', e.target.value)} placeholder="Player says..." />



                ➔
                 updateChoice(choice.id as string, 'next_question_id', e.target.value ? Number(e.target.value) : null, 'outcomes')}
                >
                  [ END CONVERSATION / RETURN TO HUB ]
                  {allSavedNodes.filter((n) => n.id !== nodeId).map((n) => (
                    Leads to Node {n.id} ({n.text.substring(0, 20)}...)
                  ))}





                 setShowAdvanced({...showAdvanced, [choice.id as string]: !showAdvanced[choice.id as string]})}>
                  {showAdvanced[choice.id as string] ? 'Hide Advanced Intel' : '⚙️ Advanced Intel & Locks'}

                 removeChoice(choice.id as string)} style={{ background: 'none', border: 'none', color: 'var(--accent-crimson)', cursor: 'pointer' }}>✕


              {/* ADVANCED MATRIX PANEL */}
              {showAdvanced[choice.id as string] && (



                  {/* GATEKEEPERS (REQUIREMENTS) */}



[ GATEKEEPERS ] (Hold Ctrl/Cmd to select multiple)




                        Requires Evidence to Say
                         updateChoice(choice.id as string, 'required_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'requirements')}>
                          {availableEvidences.map((ev) => EX-{ev.id.toString().padStart(3, '0')} {ev.title})}




                        Requires Prior Dialogue Choice
                         updateChoice(choice.id as string, 'required_choices', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'requirements')}>
                          {allAvailablePriorChoices.map((c) => {c.label})}





                  {/* REWARDS (OUTCOMES) */}



[ REWARDS & PENALTIES ]





                        Unlocks Evidence
                         updateChoice(choice.id as string, 'unlock_evidence', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'outcomes')}>
                          {availableEvidences.map((ev) => EX-{ev.id.toString().padStart(3, '0')} {ev.title})}




                        Unlocks Levels
                         updateChoice(choice.id as string, 'unlock_levels', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'outcomes')}>
                          {availableLevels.map((lv) => Level {lv.order_index}: {lv.title})}








                        Unlocks Suspects
                         updateChoice(choice.id as string, 'unlock_suspects', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'outcomes')}>
                          {availableSuspects.map((su) => {su.name})}




                        Unlocks Victims
                         updateChoice(choice.id as string, 'unlock_victims', Array.from(e.target.selectedOptions, opt => Number(opt.value)), 'outcomes')}>
                          {availableVictims.map((vi) => {vi.name})}






                       updateChoice(choice.id as string, 'gives_strike', e.target.checked, 'outcomes')} style={{ transform: 'scale(1.2)' }} />
                      Triggers Team Strike (Penalty)



              )}

          ))}

            + Add Response Branch







          {isProcessing ? 'Syncing...' : isSaved ? 'Update Node' : 'Commit New Node'}

        {isSaved && (

            Delete

        )}


  );
}

import { useState, useRef } from 'react';
import { useAdminContext } from '@/context/AdminContext';
import { useAdminMutations } from '@/hooks/useAdminMutations';
import type { Question, Choice } from '@/types';
import { type DraftChoice } from '../Shared/ChoiceEditorCard';
import { buildNodeFormData } from '../Shared/questionUtils';
import AdminLocationForm from './AdminLocationForm';
import EntityList from '../Shared/EntityList';
import './AdminLocationBuilder.css';

export default function AdminLocationBuilder() {
  const [editingId, setEditingId] = useState(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [text, setText] = useState('');
  const [storeLocally, setStoreLocally] = useState(false);
  const [image, setImage] = useState(null);
  const [existingImgUrl, setExistingImgUrl] = useState(null);
  const [audio, setAudio] = useState(null);
  const [existingAudioUrl, setExistingAudioUrl] = useState(null);

  const [activeCoordinateTarget, setActiveCoordinateTarget] = useState(null);
  const [choices, setChoices] = useState([]);

  const imageInputRef = useRef(null);
  const audioInputRef = useRef(null);

  const { caseId, levelId, setCaseId, setPhaseId, setLevelId, selectedCase, selectedPhase, selectedLevel } = useAdminContext();

  const {
    createEntity, updateEntity, deleteEntity, isProcessing,
    feedback: statusMessage, setFeedback: setStatusMessage, clearFeedback
  } = useAdminMutations('question');

  if (!caseId || !levelId || !selectedCase || !selectedPhase || !selectedLevel) {
    return (



[ MISSING CONTEXT: TARGET LEVEL REQUIRED ]

Please select a Case, Phase, and Level from the sidebar to map locations.

    );
  }

  if (selectedLevel.presentation_type !== 'location') {
    return (



[ INVALID CONTEXT: LEVEL TYPE MISMATCH ]

The currently selected level is configured for '{selectedLevel.presentation_type}'. You cannot build spatial locations here. Please select a 'Location' level from the sidebar.

    );
  }

  const clearForm = () => {
    setEditingId(null); setText(''); setStoreLocally(false);
    setImage(null); setExistingImgUrl(null); setActiveCoordinateTarget(null);
    setAudio(null); setExistingAudioUrl(null);
    setChoices([]);
    clearFeedback();
    setIsFormOpen(false);
    if (imageInputRef.current) imageInputRef.current.value = '';
    if (audioInputRef.current) audioInputRef.current.value = '';
  };

  const handleCreateNewScene = () => {
    clearForm();
    setIsFormOpen(true);
    setChoices([{ id: crypto.randomUUID(), text: '', outcomes: {}, requirements: {} }]);
  };

  const handleImageClick = (e: React.MouseEvent) => {
    if (!activeCoordinateTarget) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const xPercent = (((e.clientX - rect.left) / rect.width) * 100).toFixed(1);
    const yPercent = (((e.clientY - rect.top) / rect.height) * 100).toFixed(1);

    const targetChoice = choices.find(c => c.id === activeCoordinateTarget);
    let title = 'New Point';
    if (targetChoice && targetChoice.text.includes('|')) title = targetChoice.text.split('|')[1].trim();
    else if (targetChoice && targetChoice.text.trim() !== '') title = targetChoice.text.trim();

    setChoices(choices.map(c => c.id === activeCoordinateTarget ? { ...c, text: `${xPercent},${yPercent} | ${title}` } : c));
    setActiveCoordinateTarget(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    clearFeedback();

    if (choices.some(c => !c.text.trim())) {
      return setStatusMessage({ type: 'error', message: 'All points must have coordinate mapping text.' });
    }

    const formData = buildNodeFormData({
      level_id: levelId, text, store_locally: storeLocally, image, audio, choices
    });

    if (editingId) {
      updateEntity({ id: editingId, formData }, { onSuccess: clearForm });
    } else {
      createEntity(formData, { onSuccess: clearForm });
    }
  };

  const handleEdit = (scene: Question) => {
    setCaseId(selectedCase.id.toString());
    setPhaseId(selectedPhase.id.toString());
    setLevelId(selectedLevel.id.toString());

    setIsFormOpen(true);
    setEditingId(scene.id);
    setText(scene.text || '');

    if (scene.choices && scene.choices.length > 0) {
      setChoices(scene.choices.map((c: Choice) => ({
        id: c.id, text: c.text, requirements: c.requirements || {}, outcomes: c.outcomes || {}
      })));
    } else {
      setChoices([]);
    }

    setImage(null); setExistingImgUrl(scene.img_url || null); setActiveCoordinateTarget(null);
    setAudio(null); setExistingAudioUrl(scene.audio_url || null);
    clearFeedback();

    if (imageInputRef.current) imageInputRef.current.value = '';
    if (audioInputRef.current) audioInputRef.current.value = '';
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = (scene: Question) => {
    if (window.confirm('Are you sure you want to delete this scene?')) {
      if (editingId === scene.id) clearForm();
      deleteEntity(scene.id);
    }
  };

  const previewUrl = image ? URL.createObjectURL(image) : existingImgUrl;
  const audioPreviewUrl = audio ? URL.createObjectURL(audio) : existingAudioUrl;

  return (





// Visual Location Editor

          Targeting: {selectedCase.title} > {selectedPhase.title} > {selectedLevel.title}



      {!isFormOpen && (





              + Append New Scene



          <EntityList
            title="Location Scenes"
            items={selectedLevel.questions || []}
            emptyMessage="No scenes configured for this location yet. Click above to initialize one."
            keyExtractor={(q) => q.id}
            isProcessing={isProcessing}
            onEdit={handleEdit}
            onDelete={handleDelete}
            renderItemContent={(scene) => (






                  SCENE ID: {scene.id}

{scene.text || 'Unnamed Scene'}

{scene.choices?.length || 0} Interactable Points Mapped


            )}
          />

      )}

      {isFormOpen && (
         ${selectedPhase.title} > ${selectedLevel.title}`}
        />
      )}

  );
}

