                       addTransaction(pageIdx)} style={{ background: 'transparent', border: '1px solid #aaa', color: '#aaa', padding: '2px 8px', borderRadius: '2px', cursor: 'pointer', fontSize: '0.7rem' }}>+ Add Row


                    {(page.transactions || []).map((tx: any, txIdx: number) => (


