type TraceEvidence = Extract;

interface TraceAnalysisViewerProps {
  evidence: TraceEvidence;
}

const TraceAnalysisViewer: React.FC = ({ evidence }) => {
  const { t } = useTranslation();
  const { metadata } = evidence;

  // Deterministically generate a jagged mass spectrometry graph based on the Evidence ID
  const generatePeaks = (seed: number) => {
    let points = "0,100 ";
    for (let i = 1; i <= 20; i++) {
      const x = i * 5;
      const isMajorPeak = (seed * i) % 7 === 0;
      const y = isMajorPeak ? 10 + ((seed * i) % 20) : 75 + ((seed * i) % 20);
      points += `${x},${y} `;
    }
    points += "100,100";
    return points;
  };

  return (





{t('pages.gameRoom.evidence.viewers.traceAnalysis.advancedLab')}

{t('pages.gameRoom.evidence.viewers.traceAnalysis.massSpec')}





{t('pages.gameRoom.evidence.viewers.traceAnalysis.sampleId')} EX-{evidence.id.toString().padStart(3, '0')}

{t('pages.gameRoom.evidence.viewers.traceAnalysis.scanDate')} {new Date().toLocaleDateString()}





{t('pages.gameRoom.evidence.viewers.traceAnalysis.spectralChart')}

