): Promise<Result<{ status: string; message: string; room?: GameRoom; stats?: any }>> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/suspects/submit`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
