        'Authorization': `Bearer ${getToken()}`
      },
      body: JSON.stringify({ guilty_suspect_ids: guiltySuspectIds })
    });

    if (!response.ok) {
      if (response.status === 401) handleUnauthorized();
      const data = await response.json().catch(() => null);
      return failure(data?.message || 'Failed to submit final verdict.');
    }
    return success(await response.json());
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const submitInvestigationRequest = async (
  roomId: number,
  evidenceIds: number[]
): Promise<Result<{ status: string; message: string; unlocked_evidence: number[]; unlocked_levels?: number[] }>> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/investigate`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      },
      body: JSON.stringify({ evidence_ids: evidenceIds })
    });

    if (!response.ok) {
      if (response.status === 401) handleUnauthorized();
      const data = await response.json().catch(() => null);
      return failure(data?.message || 'The DA denied your request.');
    }
    return success(await response.json());
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const triggerWiretap = async (roomId: number, questionId: number): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/questions/${questionId}/wiretap/play`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) handleUnauthorized();
      const data = await response.json().catch(() => null);
      return failure({
        title: data?.error || 'Transmission Failed',
        message: data?.message || 'Failed to trigger wiretap.'
      });
    }
    return success(await response.json());
  } catch (error) {
    return failure({ title: 'Network Error', message: error instanceof Error ? error.message : 'Unknown error' });
  }
};

export const inspectLocation = async (roomId: number, choiceId: number): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms/${roomId}/inspect`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'Authorization': `Bearer ${getToken()}`
      },
      body: JSON.stringify({ choice_id: choiceId }),
    });

    if (!response.ok) {
      if (response.status === 401) {
        handleUnauthorized();
        return failure('Session expired.');
      }
      const data = await response.json().catch(() => null);
      return failure(data?.message || 'Failed to inspect location.');
    }

    const data = await response.json();
    return success(data);
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

import { type Result, success, failure } from '../utils/Result';

const API_BASE_URL = import.meta.env.VITE_API_URL ?? 'http://localhost:8000/api';

export interface User {
  id: number;
  username: string;
  name: string;
  email: string;
  XP: number;
}

interface AuthResponse {
  message: string;
  user: User;
  token: string;
}

export const login = async (email: string, password: string): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ email, password }),
    });

    const data = await response.json();

    if (!response.ok) return failure(data.message || 'Authentication failed');

    localStorage.setItem('auth_token', data.token);
    return success(data);
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const register = async (username: string, name: string, email: string, password: string): Promise<Result> => {
  try {
    const response = await fetch(`${API_BASE_URL}/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ username, name, email, password }),
    });

    const data = await response.json();

    if (!response.ok) return failure(data.message || 'Registration failed');

    localStorage.setItem('auth_token', data.token);
    return success(data);
  } catch (error) {
    return failure(error instanceof Error ? error.message : 'Network error');
  }
};

export const logout = () => {
  localStorage.removeItem('auth_token');
};

export const getToken = () => localStorage.getItem('auth_token');

